/**
 * Lab TTS A/B comparator — same fixed phrases, installed providers only.
 * No LLM. No downloads. Human naturalness score 1–5.
 */

import type { TtsAdapter, TtsResult } from "../contracts.ts";
import type { TtsProvider, TtsProviderInfo, TtsProviderMetrics } from "./providers.ts";
import { TTS_PROVIDER_RESEARCH_CATALOG } from "./profiles.ts";
import { wrapTtsAdapterAsProvider } from "./providers.ts";

/** Fixed lab phrases — never generated by an LLM. Phase 2C.3 battery. */
export const AB_COMPARE_PHRASES: readonly string[] = Object.freeze([
	"Hola, soy Gentle Voice. ¿En qué puedo ayudarte?",
	"Dos más dos son cuatro.",
	"Encontré tres errores en el proyecto Angular.",
	"La consulta PostgreSQL terminó correctamente.",
	"No pude completar la operación. Revisa los permisos del archivo.",
]);

export interface AbCompareTrial {
	readonly phraseIndex: number;
	readonly phrase: string;
	readonly providerId: string;
	readonly displayName: string;
	readonly synthesizeMs: number;
	readonly audioBytes: number;
	readonly sampleRateHz: number;
	/** Human MOS 1–5; undefined until scored. */
	readonly naturalness?: number;
	readonly error?: string;
}

export interface AbCompareSession {
	readonly startedAt: string;
	readonly activeProviderId: string;
	readonly installed: readonly TtsProviderInfo[];
	readonly trials: AbCompareTrial[];
}

export interface InstalledTtsSlot {
	readonly info: TtsProviderInfo;
	readonly adapter: TtsAdapter;
}

/** Only providers that are actually ready on this machine. */
export async function listInstalledTtsSlots(
	slots: readonly InstalledTtsSlot[],
): Promise<readonly InstalledTtsSlot[]> {
	const out: InstalledTtsSlot[] = [];
	for (const slot of slots) {
		const avail = await slot.adapter.availability();
		if (avail.status === "ready") out.push(slot);
	}
	return out;
}

/** Research catalog entries that are NOT selectable until installed. */
export function researchOnlyProviders(
	installedIds: ReadonlySet<string>,
): readonly TtsProviderInfo[] {
	return TTS_PROVIDER_RESEARCH_CATALOG.filter((p) => !installedIds.has(p.id));
}

export function createAbCompareSession(
	installed: readonly InstalledTtsSlot[],
	activeProviderId: string,
): AbCompareSession {
	return {
		startedAt: new Date().toISOString(),
		activeProviderId,
		installed: installed.map((s) => s.info),
		trials: [],
	};
}

export async function runAbTrial(options: {
	readonly session: AbCompareSession;
	readonly slot: InstalledTtsSlot;
	readonly phraseIndex: number;
	readonly signal?: AbortSignal;
}): Promise<{ session: AbCompareSession; trial: AbCompareTrial; result?: TtsResult }> {
	const phrase = AB_COMPARE_PHRASES[options.phraseIndex];
	if (!phrase) {
		throw new Error(`Invalid phraseIndex ${options.phraseIndex}`);
	}
	const t0 = performance.now();
	try {
		const result = await options.slot.adapter.synthesize(phrase, {
			signal: options.signal,
		});
		const synthesizeMs = Math.round(performance.now() - t0);
		const trial: AbCompareTrial = {
			phraseIndex: options.phraseIndex,
			phrase,
			providerId: options.slot.info.id,
			displayName: options.slot.info.displayName,
			synthesizeMs,
			audioBytes: result.audio.bytes.byteLength,
			sampleRateHz: result.audio.sampleRateHz,
		};
		return {
			session: {
				...options.session,
				activeProviderId: options.slot.info.id,
				trials: [...options.session.trials, trial],
			},
			trial,
			result,
		};
	} catch (error) {
		const synthesizeMs = Math.round(performance.now() - t0);
		const trial: AbCompareTrial = {
			phraseIndex: options.phraseIndex,
			phrase,
			providerId: options.slot.info.id,
			displayName: options.slot.info.displayName,
			synthesizeMs,
			audioBytes: 0,
			sampleRateHz: 0,
			error: error instanceof Error ? error.message : String(error),
		};
		return {
			session: {
				...options.session,
				trials: [...options.session.trials, trial],
			},
			trial,
		};
	}
}

/** Attach human naturalness score (1–5) to the last matching trial. */
export function scoreLastTrial(
	session: AbCompareSession,
	providerId: string,
	phraseIndex: number,
	naturalness: number,
): AbCompareSession {
	if (!Number.isInteger(naturalness) || naturalness < 1 || naturalness > 5) {
		throw new Error("naturalness must be an integer 1..5");
	}
	let lastIdx = -1;
	for (let i = session.trials.length - 1; i >= 0; i--) {
		const t = session.trials[i]!;
		if (t.providerId === providerId && t.phraseIndex === phraseIndex) {
			lastIdx = i;
			break;
		}
	}
	const trials = session.trials.map((t, i) =>
		i === lastIdx ? { ...t, naturalness } : t
	);
	return { ...session, trials };
}

export function formatAbCompareStatus(session: AbCompareSession): string {
	const lines = [
		`TTS A/B session @ ${session.startedAt}`,
		`active=${session.activeProviderId}`,
		`installed=${session.installed.map((p) => p.id).join(", ") || "(none)"}`,
		`phrases=${AB_COMPARE_PHRASES.length} (fixed; no LLM)`,
		"",
	];
	for (const t of session.trials.slice(-12)) {
		const mos = t.naturalness !== undefined ? ` mos=${t.naturalness}` : "";
		const err = t.error ? ` ERR=${t.error.slice(0, 80)}` : "";
		lines.push(
			`#${t.phraseIndex} ${t.providerId}: ${t.synthesizeMs}ms ${t.audioBytes}B${mos}${err}`,
		);
	}
	return lines.join("\n");
}

/** Wrap Piper lab adapter as the only currently selectable slot when ready. */
export function piperSlotFromAdapter(
	adapter: TtsAdapter,
	info?: Partial<TtsProviderInfo>,
): InstalledTtsSlot {
	const base = TTS_PROVIDER_RESEARCH_CATALOG.find((p) => p.id === "piper-es-AR-daniela-high")!;
	return {
		info: {
			...base,
			...info,
			id: info?.id ?? base.id,
			displayName: info?.displayName ?? base.displayName,
			engine: "piper",
			platforms: base.platforms,
			verifiedLocally: true,
			licenseHint: base.licenseHint,
			notes: info?.notes ?? base.notes,
		},
		adapter,
	};
}

export function asProvider(slot: InstalledTtsSlot): TtsProvider {
	let last: TtsProviderMetrics | undefined;
	return wrapTtsAdapterAsProvider(slot.adapter, slot.info, () => last);
}
